'use strict';
(async () => {
await window.I18n.ready;
const i18n=window.I18n,t=(key,params)=>i18n.t(key,params);
const byId=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=value=>typeof value==='number'?(Number.isFinite(value)?i18n.format(value):t('ui.unavailable')):String(value??'');
const safeUrl=value=>{try{const u=new URL(value);return u.protocol==='https:'?u.href:'#'}catch{return '#'}};
const buildModules=()=>window.COURSE_FACTORIES.flatMap(factory=>factory(t)).sort((a,b)=>a.id-b.id);
let modules=buildModules();const states=new Map();
let current=modules[0],mode='lab',frameObserver=null;
const groupFor=id=>id<=5?'01 / '+t('ui.group.foundations'):id<=10?'02 / '+t('ui.group.core'):id<=17?'03 / '+t('ui.group.products'):id<=23?'04 / '+t('ui.group.infra'):'05 / '+t('ui.group.storage');
const list=items=>`<ul>${(items||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${esc(pretty(x))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const getState=m=>{if(!states.has(m.id))states.set(m.id,{...m.lab.defaults});return states.get(m.id)};
function parsedRoute(){const aliases={scaling:1,rate:4,hash:5};const raw=location.hash.slice(1);if(aliases[raw])return{id:aliases[raw],mode:'lab'};const match=raw.match(/^chapter-(\d{1,2})(?:\/(lab|learn|exercise))?$/);return match?{id:+match[1],mode:match[2]||'lab'}:{id:1,mode:'lab'}}
function route(id,nextMode='lab',write=true){const found=modules.find(m=>m.id===id);if(!found||!['lab','learn','exercise'].includes(nextMode))return false;current=found;mode=nextMode;if(write)history.pushState(null,'',`#chapter-${String(id).padStart(2,'0')}/${mode}`);render();if(write)window.scrollTo({top:0,behavior:'instant'});return true}
function buildNav(){let group='';byId('chapter-nav').innerHTML=modules.map(m=>{const next=groupFor(m.id),heading=next!==group?`<div class="nav-group">${esc(next)}</div>`:'';group=next;return heading+`<button class="chapter-link" data-chapter="${m.id}"><span class="chapter-number">${String(m.id).padStart(2,'0')}</span><span>${esc(m.title)}</span></button>`}).join('');byId('chapter-select').innerHTML=modules.map(m=>`<option value="${m.id}">${String(m.id).padStart(2,'0')} · ${esc(m.title)}</option>`).join('');document.querySelectorAll('[data-chapter]').forEach(b=>b.addEventListener('click',()=>route(+b.dataset.chapter)));}
function bindStatic(){byId('chapter-select').addEventListener('change',e=>route(+e.target.value));document.querySelectorAll('[data-mode]').forEach(b=>{b.addEventListener('click',()=>route(current.id,b.dataset.mode));b.addEventListener('keydown',e=>{const names=['lab','learn','exercise'];let i=names.indexOf(mode);if(e.key==='ArrowRight')i=(i+1)%3;else if(e.key==='ArrowLeft')i=(i+2)%3;else if(e.key==='Home')i=0;else if(e.key==='End')i=2;else return;e.preventDefault();route(current.id,names[i]);byId('tab-'+names[i]).focus()})});byId('previous').onclick=()=>route(current.id-1);byId('next').onclick=()=>route(current.id+1)}
function render(keepLegacy=false){if(!keepLegacy){frameObserver?.disconnect();frameObserver=null;}document.title=`${String(current.id).padStart(2,'0')} · ${current.title} — System Design Lab`;byId('chapter-label').textContent=t('ui.chapterLabel',{number:String(current.id).padStart(2,'0'),group:groupFor(current.id).split(' / ')[1]});byId('chapter-title').textContent=current.title;byId('chapter-summary').textContent=current.summary;byId('chapter-count').textContent=t('ui.chapterCount',{number:current.id});byId('chapter-select').value=current.id;document.querySelectorAll('[data-chapter]').forEach(b=>{const active=+b.dataset.chapter===current.id;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false')});document.querySelectorAll('[data-mode]').forEach(b=>{const selected=b.dataset.mode===mode;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1});byId('content').setAttribute('aria-labelledby','tab-'+mode);byId('previous').disabled=current.id===1;byId('next').disabled=current.id===28;byId('previous').innerHTML=`<small>${esc(t('ui.previous'))}</small>${esc(modules.find(m=>m.id===current.id-1)?.title||t('ui.start'))}`;byId('next').innerHTML=`<small>${esc(t('ui.next'))}</small>${esc(modules.find(m=>m.id===current.id+1)?.title||t('ui.end'))}`;if(mode==='learn')renderLearn();else if(mode==='exercise')renderExercise();else if(!keepLegacy)renderLab();else{const frame=byId('legacy-frame');frame?.setAttribute('title',t('ui.labTitle',{title:current.title}));const note=document.querySelector('.legacy-note p');if(note)note.textContent=t('ui.legacyNote',{title:current.title});frame?.contentWindow?.I18n?.setLocale(i18n.locale).catch(()=>{});}}
function references(m){const refs=[{label:t('ui.source'),url:m.source},...(m.references||[]).filter(r=>r.url!==m.source)];return `<div class="references">${refs.map(r=>`<a href="${esc(safeUrl(r.url))}" target="_blank" rel="noopener noreferrer">${esc(r.label)}</a>`).join('')}</div>`}
function renderLearn(){const m=current;byId('content').innerHTML=`<div class="learning-head"><section class="card objectives"><span class="eyebrow">${esc(t('ui.objectives'))}</span><h2 style="margin-top:12px">${esc(t('ui.afterChapter'))}</h2>${list(m.objectives)}</section><section class="card"><span class="eyebrow">${esc(t('ui.architecture'))}</span><h2 style="margin-top:12px">${esc(t('ui.components'))}</h2><ol class="architecture">${(m.architecture||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p class="footnote">${esc(t('ui.archNote'))}</p></section></div><div class="content-grid">${m.sections.map((section,i)=>`<article class="card reading-card"><div class="section-index">${String(i+1).padStart(2,'0')} / ${esc(t('ui.concept'))}</div><h2>${esc(section.title)}</h2><p>${esc(section.body)}</p>${section.bullets?list(section.bullets):''}</article>`).join('')}</div><section class="subsection"><h2>${esc(t('ui.tradeoffs'))}</h2>${table([t('ui.choice'),t('ui.benefit'),t('ui.cost'),t('ui.when')],m.tradeoffs.map(t=>[t.choice,t.benefit,t.cost,t.when]))}</section><section class="card subsection pitfall-card"><h2>${esc(t('ui.pitfalls'))}</h2>${list(m.pitfalls)}</section><p class="source-note">${esc(t('ui.sourceNote'))}</p>${references(m)}`}
function renderExercise(){const ex=current.exercise;byId('content').innerHTML=`<article class="card exercise"><span class="eyebrow">${esc(t('ui.practice',{number:String(current.id).padStart(2,'0')}))}</span><h2>${esc(ex.prompt)}</h2><p>${esc(t('ui.exerciseGuide'))}</p><button id="exercise-lab" class="btn primary">${esc(t('ui.openLab'))}</button><details><summary>${esc(t('ui.hints'))}</summary>${list(ex.hints)}</details><details><summary>${esc(t('ui.solution'))}</summary><p class="solution">${esc(ex.solution)}</p></details></article>${references(current)}`;byId('exercise-lab').onclick=()=>route(current.id,'lab')}
function validateValue(control,value){if(control.type==='select'){const choice=control.options.find(o=>String(o.value)===String(value));if(!choice)throw new Error(t('ui.invalidChoice',{key:control.key}));return choice.value}if(control.type==='text'){if(typeof value!=='string'||value.length>500)throw new Error(t('ui.invalidText'));return value}const n=Number(value);if(!Number.isFinite(n)||(control.min!==undefined&&n<control.min)||(control.max!==undefined&&n>control.max))throw new Error(t('ui.invalidRange',{key:control.key}));if(control.step){const q=(n-(control.min||0))/control.step;if(Math.abs(q-Math.round(q))>1e-7)throw new Error(t('ui.invalidStep',{key:control.key}))}return n}
function controlHtml(control,state){const v=state[control.key],id='input-'+control.key;let field;if(control.type==='select')field=`<select id="${esc(id)}" data-control="${esc(control.key)}">${control.options.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(v)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;else if(control.type==='text')field=`<input type="text" maxlength="500" id="${esc(id)}" data-control="${esc(control.key)}" value="${esc(v)}">`;else field=`<input id="${esc(id)}" data-control="${esc(control.key)}" type="${control.type==='number'?'number':'range'}" min="${control.min}" max="${control.max}" step="${control.step||1}" value="${esc(v)}">${control.type==='number'?'':`<div class="ends"><span>${esc(pretty(control.min))}</span><span>${esc(pretty(control.max))} ${esc(control.unit||'')}</span></div>`}`;return `<div class="control"><label for="${esc(id)}"><span>${esc(control.label)}</span>${control.type!=='select'&&control.type!=='text'?`<output id="output-${esc(control.key)}" for="${esc(id)}">${esc(pretty(v))} ${esc(control.unit||'')}</output>`:''}</label>${field}</div>`}
function renderLab(){const m=current;if(m.legacy){byId('content').innerHTML=`<div class="legacy-note"><p>${esc(t('ui.legacyNote',{title:m.title}))}</p></div><iframe id="legacy-frame" class="legacy-frame" title="${esc(t('ui.labTitle',{title:m.title}))}" src="legacy.html?lang=${i18n.locale}#${m.legacy}"></iframe>`;const frame=byId('legacy-frame');frame.addEventListener('load',()=>{try{const doc=frame.contentDocument;const resize=()=>{frame.style.height=Math.max(700,doc.documentElement.scrollHeight)+'px'};resize();if(typeof ResizeObserver!=='undefined'){frameObserver=new ResizeObserver(resize);frameObserver.observe(doc.body)}}catch{}});return}const l=m.lab,state=getState(m);byId('content').innerHTML=`<div class="lab-heading"><div><h2>${esc(l.title)}</h2><p>${esc(l.description)}</p></div><button class="btn" id="reset-lab">${esc(t('ui.reset'))}</button></div><div class="lab-layout"><aside class="card lab-control"><h3>${esc(t('ui.configuration'))}</h3><p class="footnote" style="margin-bottom:22px">${esc(t('ui.changeInputs'))}</p>${l.controls.map(c=>controlHtml(c,state)).join('')}<div class="preset-label">${esc(t('ui.presets'))}</div><div class="presets">${(l.presets||[]).map((p,i)=>`<button class="btn" data-preset="${i}">${esc(p.label)}</button>`).join('')}</div></aside><div class="lab-results" id="lab-results" aria-live="polite" aria-atomic="false"></div></div>`;document.querySelectorAll('[data-control]').forEach(input=>{const c=l.controls.find(x=>x.key===input.dataset.control);input.addEventListener(c.type==='select'?'change':'input',()=>{try{state[c.key]=validateValue(c,input.value);const out=byId('output-'+c.key);if(out)out.textContent=pretty(state[c.key])+' '+(c.unit||'');document.querySelectorAll('[data-preset]').forEach(b=>b.classList.remove('selected'));renderLabResult()}catch{}})});document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{applyValues(l.presets[+b.dataset.preset].values);renderLab();document.querySelector(`[data-preset="${b.dataset.preset}"]`)?.classList.add('selected')});byId('reset-lab').onclick=()=>{states.set(m.id,{...l.defaults});renderLab()};renderLabResult()}
function applyValues(values){if(!values||typeof values!=='object'||Array.isArray(values))throw new Error(t('ui.invalidConfig'));const pending={};for(const [key,value]of Object.entries(values)){const c=current.lab.controls.find(x=>x.key===key);if(!c)throw new Error(t('ui.unknownParameter',{key}));pending[key]=validateValue(c,value)}Object.assign(getState(current),pending)}
function evaluateCurrent(){const result=current.lab.evaluate(Object.freeze({...getState(current)}));if(!result||!Array.isArray(result.metrics))throw new Error(t('ui.invalidResult'));return result}
function renderLabResult(){try{const r=evaluateCurrent();const palette=['#705cf0','#159775','#e5a348','#5697ce'];byId('lab-results').innerHTML=`<div class="metric-grid">${r.metrics.map(m=>`<article class="metric"><div class="metric-label">${esc(m.label)}</div><div class="metric-value">${esc(pretty(m.value))}<small>${esc(m.unit||'')}</small></div><div class="metric-note">${esc(m.note||'')}</div></article>`).join('')}</div>${r.stages?.length?`<section class="card visual-panel"><span class="eyebrow">${esc(t('ui.trace'))}</span><div class="stage-list">${r.stages.map((s,i)=>`<div class="stage"><small>${String(i+1).padStart(2,'0')}</small><h3>${esc(s.name)}</h3><p>${esc(s.detail)}</p></div>`).join('')}</div></section>`:''}<section class="insight"><span class="eyebrow">${esc(t('ui.changed'))}</span><p>${esc(r.insight)}</p></section>${r.bars?.length?`<section class="card"><h3>${esc(t('ui.comparison'))}</h3>${r.bars.map((b,i)=>{const ratio=b.max>0?Math.max(0,Math.min(100,b.value/b.max*100)):0;return `<div class="bar-row"><span>${esc(b.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${ratio}%;background:${palette[i%palette.length]}"></div></div><span class="bar-value">${esc(pretty(b.value))} ${esc(b.unit||'')}</span></div>`}).join('')}</section>`:''}${r.table?`<section class="subsection">${table(r.table.headers,r.table.rows)}</section>`:''}<details class="card assumptions" open><summary>${esc(t('ui.assumptions'))}</summary>${list(r.assumptions||[])}<p class="footnote">${esc(t('ui.educational'))}</p></details>`}catch(error){byId('lab-results').innerHTML=`<div class="empty-error">${esc(t('ui.modelError'))}</div>`;console.error('Lab evaluation failed',current.id,error)}}
if(modules.length!==28||new Set(modules.map(m=>m.id)).size!==28){byId('content').innerHTML=`<div class="empty-error">${esc(t('ui.loadError'))}</div>`;return}
buildNav();bindStatic();document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();byId('content').focus()});const start=parsedRoute();if(!route(start.id,start.mode,false))route(1,'lab',false);window.addEventListener('hashchange',()=>{const r=parsedRoute();route(r.id,r.mode,false)});window.addEventListener('popstate',()=>{const r=parsedRoute();route(r.id,r.mode,false)});
const language=byId('language-select');
language.innerHTML=i18n.languages.map(l=>`<option value="${esc(l.code)}">${esc(l.name)}</option>`).join('');language.value=i18n.locale;
language.addEventListener('change',async()=>{language.disabled=true;byId('language-status').textContent='';try{await i18n.setLocale(language.value)}catch{byId('language-status').textContent=t('ui.languageError');language.value=i18n.locale}finally{language.disabled=false}});
window.addEventListener('languagechange',()=>{const chapter=current.id;const keep=mode==='lab'&&Boolean(current.legacy)&&Boolean(byId('legacy-frame'));modules=buildModules();current=modules.find(m=>m.id===chapter);buildNav();render(keep);language.value=i18n.locale;});
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'open_system_design_chapter',title:t('ui.tool.openTitle'),description:t('ui.tool.openDescription'),inputSchema:{type:'object',properties:{chapter:{type:'integer',minimum:1,maximum:28},mode:{type:'string',enum:['lab','learn','exercise']}},required:['chapter'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isInteger(input.chapter)||Object.keys(input).some(k=>!['chapter','mode'].includes(k))||!route(input.chapter,input.mode||'lab'))throw new Error(t('ui.invalidChapter'));return{chapter:current.id,title:current.title,mode}}});register({name:'configure_system_design_lab',title:t('ui.tool.configureTitle'),description:t('ui.tool.configureDescription'),inputSchema:{type:'object',properties:{values:{type:'object'}},required:['values'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(current.legacy)throw new Error(t('ui.visualControls'));if(!input||Object.keys(input).some(k=>k!=='values'))throw new Error(t('ui.invalidInput'));applyValues(input.values);mode='lab';history.replaceState(null,'',`#chapter-${String(current.id).padStart(2,'0')}/lab`);render();return{chapter:current.id,values:{...getState(current)},metrics:evaluateCurrent().metrics}}})}
})().catch(error=>{console.error('Course initialization failed',error);document.getElementById('content').textContent='Materi gagal dimuat / Lessons could not load. Please reload.';});
